output_text:
[
  {
    "id": "get_cart_eventually",
    "text": "A shopper should obtain a cart during the trip before completing the shopping episode.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    },
    "justification": "The rule refers to the general shopping role of using a cart, not to any particular cart-bay coordinate or floor-plan location."
  },
  {
    "id": "exit_with_cart",
    "text": "A shopper must not leave the store without still having the cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The rule is expressed in terms of the exit action and cart possession, so it applies regardless of where the exit is placed."
  },
  {
    "id": "no_cart_in_single_file_passage",
    "text": "A shopper must not push a cart while occupying a single-file passage.",
    "abstraction": {
      "state_properties": {
        "singleFilePassage": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFilePassage"
        ]
      }
    },
    "justification": "Single-file width is a layout-independent geometric relation that can be evaluated in any store without naming cells."
  },
  {
    "id": "do_not_enter_single_file_with_cart",
    "text": "A shopper must not move a cart into a single-file passage.",
    "abstraction": {
      "state_properties": {
        "singleFilePassage": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "singleFilePassage"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    },
    "justification": "The rule constrains transitions into narrow passages rather than any named aisle or coordinate."
  },
  {
    "id": "no_cart_shelf_interaction_in_restricted_aisle",
    "text": "A shopper must not interact with shelf merchandise while holding a cart in a cart-restricted shelf aisle.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS"
              ]
            }
          ]
        },
        "singleFilePassage": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "cartRestrictedShelfAisle": {
          "and": [
            "adjShelf",
            {
              "or": [
                "singleFilePassage",
                "betweenOpposingShelves"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "cartRestrictedShelfAisle"
        ]
      }
    },
    "justification": "The abstraction uses shelf adjacency, opposing shelves, and aisle width, all of which describe functional aisle type rather than store-specific positions."
  },
  {
    "id": "park_cart_only_in_wide_clear_area",
    "text": "A shopper may set down a cart only in a wide clear area away from shelves.",
    "abstraction": {
      "state_properties": {
        "wideClearArea": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "ge": [
                "freeWidthV",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "setDownCart",
          {
            "not": "wideClearArea"
          }
        ]
      }
    },
    "justification": "The rule characterizes suitable cart-parking places by clearance and shelf proximity, not by fixed coordinates."
  },
  {
    "id": "retrieve_cart_after_setting_down",
    "text": "If a shopper sets down a cart, they must later pick up a cart again before the episode ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "setDownCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "setDownCart",
      "discharge": "pickUpCart"
    },
    "justification": "The rule depends only on the abstract event of leaving and recovering a cart, so it is meaningful in any layout."
  },
  {
    "id": "retrieve_cart_after_on_foot_shelf_access",
    "text": "After accessing a shelf while not holding a cart, a shopper must return to having a cart.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "onFootShelfAccess": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              },
              "adjShelf"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootShelfAccess",
      "discharge": "hasCart"
    },
    "justification": "The trigger is defined by the shopper's relation to shelves and cart possession rather than by the identity or coordinate of the aisle."
  }
]
